import type { Metadata } from "next";

/** Shared text for search results, link previews and the installed app. */
export const SITE_NAME = "Starlight English";
export const SITE_TITLE = "Starlight English — Year 7 English practice, one star at a time";
export const SITE_DESCRIPTION =
  "A game for Year 7 English Speakers' Programme students: practise novels, short stories, poetry, grammar and spelling in 20 minutes a day. Every mistake comes back until it's mastered.";

/** 1200×630 link-preview image, generated by `npm run assets:og`. */
export const OG_IMAGE = {
  url: "/og.jpg",
  width: 1200,
  height: 630,
  type: "image/jpeg",
  alt: "Starlight English: Nova the fox waving on a lantern-lit path at dusk. Light up the sky, one word at a time.",
};

/**
 * The public address of the site, used to turn relative links (canonical URLs, preview images,
 * sitemap entries) into the absolute ones crawlers and chat apps require.
 * NEXT_PUBLIC_SITE_URL wins (set it when using a custom domain); on Vercel the production
 * domain is filled in automatically.
 */
export function siteUrl(): URL {
  const explicit = process.env.NEXT_PUBLIC_SITE_URL;
  if (explicit) return new URL(explicit);
  const vercel = process.env.VERCEL_PROJECT_PRODUCTION_URL;
  if (vercel) return new URL(`https://${vercel}`);
  return new URL(`http://localhost:${process.env.PORT || 3000}`);
}

/** Pages anyone may see and search engines may list. Everything else needs a sign-in. */
export const PUBLIC_PAGES = ["/", "/join", "/parent/signup", "/parent/login"] as const;

/** For signed-in pages: keep them out of search results. */
export const PRIVATE_PAGE: Metadata["robots"] = { index: false, follow: false };

/**
 * Metadata for a public page: its canonical address plus a link preview with this page's
 * own title and description (a page-level `openGraph` replaces the layout's, so the image is
 * repeated here).
 */
export function publicPage(path: (typeof PUBLIC_PAGES)[number], title: string, description: string): Metadata {
  return {
    title: path === "/" ? { absolute: title } : title,
    description,
    alternates: { canonical: path },
    openGraph: { type: "website", siteName: SITE_NAME, locale: "en_GB", url: path, title, description, images: [OG_IMAGE] },
    twitter: { card: "summary_large_image", title, description, images: [OG_IMAGE] },
  };
}
